begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_column('public','org_settings','require_different_payment_reviewer','Payment review separation is optional per organization');

create function pg_temp.pid(n integer) returns uuid language sql immutable as $$select ('ce000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email) values(pg_temp.pid(1),'review-owner@example.invalid'),(pg_temp.pid(2),'review-admin@example.invalid');
insert into public.organizations(id,name,slug) values(pg_temp.pid(10),'Review policy','review-policy-tests');
insert into public.memberships(org_id,user_id,role) values(pg_temp.pid(10),pg_temp.pid(1),'owner'),(pg_temp.pid(10),pg_temp.pid(2),'admin');
insert into public.clients(id,org_id,name) values(pg_temp.pid(20),pg_temp.pid(10),'Buyer');
insert into public.invoices(id,org_id,client_id,number) values(pg_temp.pid(30),pg_temp.pid(10),pg_temp.pid(20),'DRAFT-POLICY');
insert into public.invoice_items(org_id,invoice_id,description,unit_price_satang) values(pg_temp.pid(10),pg_temp.pid(30),'Service',10000);
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.pid(1))::text,true);
set local role authenticated;
select public.update_business_profile(pg_temp.pid(10),'Seller','Address',null,'not_registered');
select public.issue_invoice(org_id,id,version,pg_temp.pid(49)) from public.invoices where id=pg_temp.pid(30);
select public.update_payment_review_policy(pg_temp.pid(10),true);
select public.submit_internal_payment_claim(pg_temp.pid(10),pg_temp.pid(30),1000,'Internal transfer',pg_temp.pid(50));
select public.submit_customer_payment_claim(pg_temp.pid(10),pg_temp.pid(20),2000,'[]','General transfer',pg_temp.pid(51));
select throws_ok($$select public.review_payment_claim_with_evidence(pg_temp.pid(10),(select id from public.payment_claims where org_id=pg_temp.pid(10) and invoice_id is not null),1000,'Bank evidence',pg_temp.pid(52),'verified',current_date,'transfer')$$,'P0001','A different staff member must verify this reported receipt','Reporter cannot verify invoice receipt when enabled');
select throws_ok($$select public.review_payment_claim_with_evidence(pg_temp.pid(10),(select id from public.payment_claims where org_id=pg_temp.pid(10) and invoice_id is null),2000,'Bank evidence',pg_temp.pid(53),'verified',current_date,'transfer')$$,'P0001','A different staff member must verify this reported receipt','Reporter cannot verify unallocated receipt when enabled');
select is((select count(*) from public.payments where org_id=pg_temp.pid(10)),0::bigint,'Failed reviews roll back cash and allocations');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.pid(2))::text,true);
select lives_ok($$select public.review_payment_claim_with_evidence(pg_temp.pid(10),(select id from public.payment_claims where org_id=pg_temp.pid(10) and invoice_id is not null),1000,'Admin bank evidence',pg_temp.pid(54),'verified',current_date,'transfer')$$,'Different admin verifies receipt');
select public.update_payment_review_policy(pg_temp.pid(10),false);
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.pid(1))::text,true);
select lives_ok($$select public.review_payment_claim_with_evidence(pg_temp.pid(10),(select id from public.payment_claims where org_id=pg_temp.pid(10) and invoice_id is null),2000,'Owner bank evidence',pg_temp.pid(55),'verified',current_date,'transfer')$$,'Optional policy can be disabled');
select * from finish();
rollback;
